//   generate-mc-types bedrock 1.21.130 1.26.0 1.26.10 1.26.20 1.26.30 1.26.40 1.26.45 1.26.51 --merge --name Bedrock
//     --out packages/mineflayer/types/protocol --data packages/minecraft-data/minecraft-data/data
import { MCProtocol } from './types/protocol/bedrock.js';

type Packets = MCProtocol.Bedrock.Read.Clientbound.Packets & MCProtocol.Bedrock.Read.Serverbound.Packets;

declare global {
  export import protocolTypes = MCProtocol.Bedrock.Read.Types;
  /** a listener for each packet, by name */
  type BedrockPacketEventMap = { [K in keyof Packets]: (packet: Packets[K]) => void };
}

export { MCProtocol };
export import protocolTypes = MCProtocol.Bedrock.Read.Types;
export type BedrockPacketEventMap = { [K in keyof Packets]: (packet: Packets[K]) => void };
